// ta = Tamil, te = Telugu, kn = Kannada, ml = Malayalam
//
// NOTE ON TRANSLATION METHODOLOGY (district names):
// - Hindi (hi) labels were authored directly.
// - Marathi (mr) reuses the Hindi Devanagari spelling, which is standard
//   practice for Indian place names shared across Devanagari-script languages.
// - Punjabi (pa) and Gujarati (gu) are derived from the Hindi spelling via a
//   direct Unicode block mapping (Devanagari/Gurmukhi/Gujarati share an almost
//   identical letter-for-letter layout), which is accurate for these three
//   scripts.
// - Tamil (ta), Telugu (te), Kannada (kn) and Malayalam (ml) use their own
//   established native spelling for districts inside their home state
//   (Tamil Nadu / Andhra Pradesh & Telangana / Karnataka / Kerala). For
//   districts elsewhere in the country, these four are auto-derived phonetic
//   renderings and are a best-effort approximation, not an official spelling -
//   review before using in a legal/government-facing context if precision
//   for out-of-state districts matters.

