/*
|--------------------------------------------------------------------------
| HELPERS
|--------------------------------------------------------------------------
|
| IMPORTANT: These helpers always return/accept the canonical English
| "code" as the value (for forms, database storage, etc). The "label"
| field is ONLY for display and changes with `lang`. Never store a
| localized label as a database value.
|
*/

const SUPPORTED_LANGS = ['en', 'hi', 'pa', 'gu', 'mr', 'ta', 'te', 'kn', 'ml'];

function resolveLabel(nameObj, lang, fallbackCode) {
  if (!nameObj) return fallbackCode;
  return nameObj[lang] || nameObj.en || fallbackCode;
}

export function getStateOptions(lang = 'en') {
  return INDIA_LOCATIONS
    .map((state) => ({
      code: state.code,
      label: resolveLabel(state.name, lang, state.code),
    }))
    .sort((a, b) => a.label.localeCompare(b.label, lang));
}

export function getDistrictOptions(stateCode, lang = 'en') {
  const state = INDIA_LOCATIONS.find((item) => item.code === stateCode);

  if (!state) return [];

  return state.districts
    .map((district) => {
      // Supports both the current object shape ({ code, name }) and a
      // legacy plain-string district, so older data/back-ups won't crash.
      const code = typeof district === 'string' ? district : district.code;
      const label =
        typeof district === 'string'
          ? district
          : resolveLabel(district.name, lang, code);

      return { code, label };
    })
    .sort((a, b) => a.label.localeCompare(b.label, lang));
}

export function getStateLabel(stateCode, lang = 'en') {
  const state = INDIA_LOCATIONS.find((item) => item.code === stateCode);

  if (!state) return stateCode;

  return resolveLabel(state.name, lang, stateCode);
}

export function getDistrictLabel(stateCode, districtCode, lang = 'en') {
  const state = INDIA_LOCATIONS.find((item) => item.code === stateCode);

  if (!state) return districtCode;

  const district = state.districts.find((item) =>
    typeof item === 'string' ? item === districtCode : item.code === districtCode
  );

  if (!district) return districtCode;

  if (typeof district === 'string') return district;

  return resolveLabel(district.name, lang, districtCode);
}

export { SUPPORTED_LANGS };